		if (areset)
			state <= Idle;
		else begin
			case (state)
				Idle: 
					if (go_up) state <= Moving_Up;
					else if (go_down) state <= Moving_Down;
				Moving_Up:
					if (floor_reached) state <= Idle;
				Moving_Down:
					if (floor_reached) state <= Idle;
			endcase
		end
	end

	assign door_open = (state == Idle);
	assign moving_up = (state == Moving_Up);
	assign moving_down = (state == Moving_Down);

endmodule

