  input   [31:0] i_data0;
  output  [31:0]
    o_data0;

  //Multipliers:

  wire [31:0]
    w1,
    w128,
    w127,
    w256,
    w257,
    w64,
    w321,
    w2032,
    w1711;

  assign w1 = i_data0;
  assign w128 = i_data0 << 7;
  assign w127 = w128 - w1;
  assign w256 = i_data0 << 8;
  assign w257 = w1 + w256;
  assign w64 = i_data0 << 6;
  assign w321 = w257 + w64;
  assign w2032 = w127 << 4;
