    input logic [3:0] input_num,
    output logic [2:0] output_mag
);always_comb begin
        case(input_num)
            4'b0000: output_mag = 3'b000;
            4'b0001, 4'b0010: output_mag = 3'b001;
            4'b0011, 4'b0100, 4'b1000: output_mag = 3'b010;
